#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# One-time Azure setup for deploying capacity-planning to Azure Container Apps (#20).
# Run from anywhere inside the repo:  ./scripts/azure-setup.sh
# Safe to re-run: existing resources are detected and reused.
#
# The container apps themselves are created/updated by the GitHub Actions deploy
# workflow (#21); this wizard prepares everything that workflow needs.

TOTAL_STAGES=6

GITHUB_REPO="amarpandav/capacity-planning"
DEPLOYER_APP_NAME="cpt-github-deployer"
FEDERATED_CREDENTIAL_NAME="github-main"

cd "$(git rev-parse --show-toplevel)"
ENV_FILE=".env.azure"   # local only (git-ignored); remembers answers between runs

# ask_default KEY "Prompt" DEFAULT: like ask, but falls back to DEFAULT on empty input.
ask_default() {
  local key="$1" prompt="$2" default="$3"
  ask "$key" "$prompt ${DIM}(default: $default)${RESET}"
  [[ -n "${!key}" ]] || printf -v "$key" '%s' "$default"
}

banner "Azure setup for capacity-planning (Container Apps)"

# ── Stage 1 ────────────────────────────────────────────────────────────────
stage "Sign in to Azure"
if ! command -v az >/dev/null 2>&1; then
  warn "Azure CLI not found. Install it with: brew install azure-cli"; exit 1
fi
if ! gh auth status >/dev/null 2>&1; then
  warn "GitHub CLI is not signed in. Run: gh auth login"; exit 1
fi
if az account show >/dev/null 2>&1; then
  say "Already signed in to Azure as $(az account show --query user.name -o tsv)."
else
  if confirm "Do you need to create an Azure account first?"; then
    open_url "https://azure.microsoft.com/free"
    step "Create the account (a free account comes with a subscription)."
    pause "Press Enter once your account is ready."
  fi
  step "A browser window opens next: sign in with your Azure account."
  pause "Press Enter to sign in."
  # skip the CLI's own subscription picker; the wizard asks for the subscription next
  AZURE_CORE_LOGIN_EXPERIENCE_V2=off az login --only-show-errors >/dev/null
fi
say "Your subscriptions:"
az account list --query "[].{Name:name, SubscriptionId:id, Default:isDefault}" -o table | sed 's/^/    /'
ask_default AZURE_SUBSCRIPTION_ID "Subscription ID to use:" "$(az account show --query id -o tsv)"
az account set --subscription "$AZURE_SUBSCRIPTION_ID"
AZURE_TENANT_ID=$(az account show --query tenantId -o tsv)
write_env AZURE_SUBSCRIPTION_ID "$AZURE_SUBSCRIPTION_ID"
write_env AZURE_TENANT_ID "$AZURE_TENANT_ID"

# ── Stage 2 ────────────────────────────────────────────────────────────────
stage "Region and resource names"
note "Container Apps costs the same in most regions (West Europe is ~40% more); pick one near your users."
ask_default AZURE_LOCATION "Azure region:" "centralindia"
ask_default AZURE_RESOURCE_GROUP "Resource group:" "cpt-demo-rg"
ask_default AZURE_CONTAINERAPPS_ENV "Container Apps environment:" "cpt-env"
ask_default AZURE_BACKEND_APP "Backend container app:" "cpt-web-app"
ask_default AZURE_UI_APP "UI container app:" "cpt-ui"
for key in AZURE_LOCATION AZURE_RESOURCE_GROUP AZURE_CONTAINERAPPS_ENV AZURE_BACKEND_APP AZURE_UI_APP; do
  write_env "$key" "${!key}"
done

# ── Stage 3 ────────────────────────────────────────────────────────────────
stage "Azure prerequisites"
say "Adding the Container Apps CLI extension and registering the Microsoft.App provider…"
az extension add --name containerapp --upgrade --only-show-errors >/dev/null
az provider register --namespace Microsoft.App --wait --only-show-errors
supported=$(az provider show --namespace Microsoft.App \
  --query "resourceTypes[?resourceType=='managedEnvironments'].locations[]" -o tsv \
  | tr '[:upper:]' '[:lower:]' | tr -d ' ')
if ! grep -qx "$AZURE_LOCATION" <<<"$supported"; then
  warn "Container Apps is not available in '$AZURE_LOCATION'. Re-run and pick another region."; exit 1
fi
printf '  %s✓%s Container Apps is available in %s\n' "$GREEN" "$RESET" "$AZURE_LOCATION"

# ── Stage 4 ────────────────────────────────────────────────────────────────
stage "Resource group and Container Apps environment"
say "Resource group:  $AZURE_RESOURCE_GROUP ($AZURE_LOCATION)"
say "Environment:     $AZURE_CONTAINERAPPS_ENV (Consumption plan, logs off)"
note "An empty Consumption environment costs nothing; apps only bill while running (free monthly grant applies)."
if confirm "Create them now (existing ones are reused)?"; then
  az group create --name "$AZURE_RESOURCE_GROUP" --location "$AZURE_LOCATION" -o none
  printf '  %s✓%s resource group ready\n' "$GREEN" "$RESET"
  if az containerapp env show --name "$AZURE_CONTAINERAPPS_ENV" --resource-group "$AZURE_RESOURCE_GROUP" -o none 2>/dev/null; then
    printf '  %s✓%s environment already exists\n' "$GREEN" "$RESET"
  else
    say "Creating the environment (takes a few minutes)…"
    az containerapp env create --name "$AZURE_CONTAINERAPPS_ENV" --resource-group "$AZURE_RESOURCE_GROUP" \
      --location "$AZURE_LOCATION" --logs-destination none -o none --only-show-errors
    printf '  %s✓%s environment created\n' "$GREEN" "$RESET"
  fi
else
  SKIPPED+=("resource group + Container Apps environment (re-run this wizard)")
fi

# ── Stage 5 ────────────────────────────────────────────────────────────────
stage "GitHub deploy identity (passwordless)"
say "GitHub Actions will sign in to Azure with a short-lived token (OIDC); no password is stored."
say "App registration:  $DEPLOYER_APP_NAME"
say "Trusted workflow:  $GITHUB_REPO, branch main"
say "Permission:        Contributor on resource group $AZURE_RESOURCE_GROUP only"
if confirm "Create or update it now?"; then
  AZURE_CLIENT_ID=$(az ad app list --display-name "$DEPLOYER_APP_NAME" --query "[0].appId" -o tsv)
  if [[ -z "$AZURE_CLIENT_ID" ]]; then
    AZURE_CLIENT_ID=$(az ad app create --display-name "$DEPLOYER_APP_NAME" --query appId -o tsv)
    printf '  %s✓%s app registration created\n' "$GREEN" "$RESET"
  else
    printf '  %s✓%s app registration already exists\n' "$GREEN" "$RESET"
  fi
  sp_object_id=$(az ad sp show --id "$AZURE_CLIENT_ID" --query id -o tsv 2>/dev/null || true)
  [[ -n "$sp_object_id" ]] || sp_object_id=$(az ad sp create --id "$AZURE_CLIENT_ID" --query id -o tsv)

  if [[ "$(az ad app federated-credential list --id "$AZURE_CLIENT_ID" \
        --query "length([?name=='$FEDERATED_CREDENTIAL_NAME'])" -o tsv)" == "0" ]]; then
    az ad app federated-credential create --id "$AZURE_CLIENT_ID" -o none --parameters "{
      \"name\": \"$FEDERATED_CREDENTIAL_NAME\",
      \"issuer\": \"https://token.actions.githubusercontent.com\",
      \"subject\": \"repo:$GITHUB_REPO:ref:refs/heads/main\",
      \"audiences\": [\"api://AzureADTokenExchange\"]
    }"
  fi
  printf '  %s✓%s federated credential for main ready\n' "$GREEN" "$RESET"

  scope="/subscriptions/$AZURE_SUBSCRIPTION_ID/resourceGroups/$AZURE_RESOURCE_GROUP"
  if [[ "$(az role assignment list --assignee "$sp_object_id" --scope "$scope" --role Contributor \
        --query "length(@)" -o tsv)" == "0" ]]; then
    # a brand-new service principal can take a moment to replicate; retry briefly
    for attempt in 1 2 3 4 5 6; do
      az role assignment create --assignee-object-id "$sp_object_id" --assignee-principal-type ServicePrincipal \
        --role Contributor --scope "$scope" -o none --only-show-errors 2>/dev/null && break
      [[ $attempt == 6 ]] && { warn "Role assignment failed; re-run the wizard in a minute."; exit 1; }
      sleep 10
    done
  fi
  printf '  %s✓%s Contributor on %s\n' "$GREEN" "$RESET" "$AZURE_RESOURCE_GROUP"

  write_env AZURE_CLIENT_ID "$AZURE_CLIENT_ID"
  set_secret AZURE_CLIENT_ID "$AZURE_CLIENT_ID"
  set_secret AZURE_TENANT_ID "$AZURE_TENANT_ID"
  set_secret AZURE_SUBSCRIPTION_ID "$AZURE_SUBSCRIPTION_ID"
  for key in AZURE_LOCATION AZURE_RESOURCE_GROUP AZURE_CONTAINERAPPS_ENV AZURE_BACKEND_APP AZURE_UI_APP; do
    set_var "$key" "${!key}"
  done
else
  SKIPPED+=("GitHub deploy identity + GitHub secrets/variables (re-run this wizard)")
fi

# ── Stage 6 ────────────────────────────────────────────────────────────────
stage "Optional: budget alert"
say "A budget emails you if the demo ever starts costing money. Recommended, takes a minute."
if confirm "Set up a monthly budget alert?"; then
  open_url "https://portal.azure.com"
  step "In the top search bar, type 'Budgets' and open Cost Management | Budgets."
  step "Check the scope at the top is your subscription, then click '+ Add'."
  step "Name: cpt-demo-budget · Reset period: Monthly · Amount: 5 (in your billing currency)."
  step "Next → Alert conditions: Type Actual, 80 % · add your email under Alert recipients."
  step "Click Create."
  pause "Press Enter once the budget is created."
else
  note "Skipped. You can add one later in Cost Management → Budgets."
fi

finish
note "Next: the deploy workflow (#21) uses the GitHub secrets and variables set above."
